; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: cpcfw (Amstrad CPC - firmware text and keys), starts in normal mode
; ============================================================

			DEVICE AMSTRADCPC6128		; for SAVEAMSDOS at the end
			org #0040

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI, 3 ADM-3A, 4 Televideo (CP/M)
NTC_TERM_RT	equ 0		; 1: the program calls StdIO.SetTerminal (the terminal is chosen while it runs)
NTC_STRMAX	equ 255		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 1		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 1		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_WINPAGED	equ 0		; 1 = page 0 code may sit under the window (Option Memory Paged, not Reserved): the Memory class never hands out page 1 (main RAM's own #4000-#7FFF) when the code reaches past #4000
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_ISLN	equ 1		; interrupt classes (Option Class Interrupt): the slots ntc_isl has (8 bytes each)
NTC_INTS	equ 1		; 0 = the platform never lets interrupts in (;@ints 0: ntc_xn's safe point has no ei)
NTC_PLATRSV	equ 0		; 1 = the platform's fixed areas (;@reserved) are Reserved in the memory map: the build goes round them (the old top-of-RAM asserts are off)
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)

ntc_start:
			jr ntc_start2
ntc_bk_sp:		dw 0			; #0042: main RAM's SP while a bank runs
ntc_bk_out:
			out (c), c		; #0044: BC = the other side's RAM setting
			jp ntc_bk_land		; #0046: main RAM switched in
ntc_bk_land:
			ld sp, (ntc_bk_sp)
			ret				; to where main RAM handed over
			ASSERT ntc_bk_out == #0044, "the bank switch must be at #0044"
ntc_start2:
			di
			call ntc_rj_find		; Library: ROM - find the ROM, patch the jump block
			jr nc, ntc_rj_ok
			ei
			ret				; no ROM (the message is shown): back to the caller
ntc_rj_ok:
			di				; (KL ROM SELECT lets interrupts in again)
			ld hl, ntc_rj_exit
			push hl			; End comes back here: the caller's ROM selection again
			ld (ntc_csp), sp
			ld a, (#BC77)		; Option RomEnable: start the ROMs again
			cp #DF			; AMSDOS has the cassette calls: they are running
			jp z, ntc_roms_on
			ei
			ld de, #A5F0		; the lowest address the ROMs may use (the keyword ROM's RAM is below)
			ld hl, #ABFF		; the highest (as usual for AMSDOS: it takes about #A700-#ABFF)
			ld c, 7
			call #BCCE		; KL INIT BACK: ROM 7 (DE / HL come back as the new limits)
			inc hl			; the first byte the ROMs took
			ld (ntc_roms_at), hl
			ld de, #A600
			or a
			sbc hl, de
			jp nc, ntc_roms_fit	; AMSDOS alone (or no more): as usual
			ld hl, ntc_roms_msg
			call ntc_roms_puts
			ld a, (ntc_roms_at + 1)
			call ntc_roms_hex
			ld a, (ntc_roms_at)
			call ntc_roms_hex
			ld hl, ntc_roms_msg2
			call ntc_roms_puts
			call #BB06		; KM WAIT CHAR
			rst 0			; (the machine starts again)
ntc_roms_puts:
			ld a, (hl)
			or a
			ret z
			call #BB5A		; TXT OUTPUT
			inc hl
			jr ntc_roms_puts
ntc_roms_hex:
			push af
			rrca
			rrca
			rrca
			rrca
			call ntc_roms_dig
			pop af
ntc_roms_dig:
			and 15
			add a, #90
			daa
			adc a, #40
			daa
			jp #BB5A
ntc_roms_at:	dw 0
ntc_roms_msg:	db "The ROMs' RAM reaches down to #", 0
ntc_roms_msg2:	db ": no room for this program", 13, 10, "(fewer ROMs, or a smaller program)", 13, 10, "Press a key", 13, 10, 0
ntc_roms_fit:
			di
			IF NTC_PLATRSV == 0		; (with the platform's #A600-#BFFF Reserved in the map, the build goes round it)
			ASSERT ntc_free <= #A600, "Option RomEnable: the program and its arrays must end below #A600 (the ROMs take their RAM from #ABFF down)"
			ENDIF
ntc_roms_on:
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; main.bas 21: Print "Files on "; System.Platform
			dw kw_printstrvar, str1
			dw kw_printnl

			; main.bas 22: Print "LOAD "; FileSystem.Capability("LOAD"); "  SAVE "; FileSystem.Capability("SAVE")
			dw fn_filesystem_capability, str2, var_filesystem_capability_capability
			dw kw_printstrvar, str3
			dw kw_printint, var_filesystem_capability_capability
			dw fn_filesystem_capability, str4, var_filesystem_capability_capability
			dw kw_printstrvar, str5
			dw kw_printint, var_filesystem_capability_capability
			dw kw_printnl

			; main.bas 23: Print "SEQUENTIAL "; FileSystem.Capability("SEQUENTIAL"); "  RANDOMACCESS "; FileSystem.Capability("RANDOMACCESS")
			dw fn_filesystem_capability, str6, var_filesystem_capability_capability
			dw kw_printstrvar, str7
			dw kw_printint, var_filesystem_capability_capability
			dw fn_filesystem_capability, str8, var_filesystem_capability_capability
			dw kw_printstrvar, str9
			dw kw_printint, var_filesystem_capability_capability
			dw kw_printnl

			; main.bas 24: Print "MAXOPEN "; FileSystem.Capability("MAXOPEN")
			dw fn_filesystem_capability, str10, var_filesystem_capability_capability
			dw kw_printstrvar, str11
			dw kw_printint, var_filesystem_capability_capability
			dw kw_printnl

			; main.bas 25: If FileSystem.Capability("DEVICES") Then Print "Devices "; FileSystem.Devices(); " - using "; FileSystem.CurrentDevice()
			dw fn_filesystem_capability, str12, var_filesystem_capability_capability
			dw kw_goto_ifzero_n, var_filesystem_capability_capability, if1_1
			dw fn_filesystem_devices, var_filesystem_devices_devices
			dw kw_printstrvar, str13
			dw kw_printstrvar, var_filesystem_devices_devices
			dw fn_filesystem_currentdevice, var_filesystem_currentdevice_currentdevice
			dw kw_printstrvar, str14
			dw kw_printstrvar, var_filesystem_currentdevice_currentdevice
			dw kw_printnl
if1_1:

			; main.bas 26: If FileSystem.Capability("VOLUMES") Then Print "Volumes known "; FileSystem.Volumes(); " - using "; FileSystem.CurrentVolume()
			dw fn_filesystem_capability, str15, var_filesystem_capability_capability
			dw kw_goto_ifzero_n, var_filesystem_capability_capability, if2_1
			dw fn_filesystem_volumes, var_filesystem_volumes_volumes
			dw kw_printstrvar, str16
			dw kw_printstrvar, var_filesystem_volumes_volumes
			dw fn_filesystem_currentvolume, var_filesystem_currentvolume_currentvolume
			dw kw_printstrvar, str14
			dw kw_printstrvar, var_filesystem_currentvolume_currentvolume
			dw kw_printnl
if2_1:

			; main.bas 27: Print
			dw kw_printnl

			; main.bas 29: If FileSystem.Capability("SAVE") Then
			dw fn_filesystem_capability, str4, var_filesystem_capability_capability
			dw kw_goto_ifzero_n, var_filesystem_capability_capability, if3_1

			; main.bas 30: For i = 0 To 9 : hs(i) = 1000 - i * 50 : Next
			dw kw_ztov, var_i
for4_t:
			dw kw_mulvl, var_i, 50, tmp2
			dw kw_sublv, 1000, tmp2, tmp1
			dw kw_aset, arr_hs, var_i, tmp1
			dw kw_next1l_n, var_i, 9, for4_t
for4_e:

			; main.bas 31: r = FileSystem.Save("HISCORE.DAT", VarPtr(hs), 20)
			dw fn_filesystem_save, str17, vp_arr_hs, lit_20, var_r

			; main.bas 32: Print "Save HISCORE.DAT: "; r
			dw kw_printstrvar, str18
			dw kw_printint, var_r
			dw kw_printnl

			; main.bas 33: If FileSystem.Capability("LOAD") Then
			dw fn_filesystem_capability, str2, var_filesystem_capability_capability
			dw kw_goto_ifzero_n, var_filesystem_capability_capability, if3_e

			; main.bas 34: r = FileSystem.Load("HISCORE.DAT", VarPtr(back), 20)
			dw fn_filesystem_load, str17, vp_arr_back, lit_20, var_r

			; main.bas 35: Print "Load: "; r; " bytes, "; back(0); " ... "; back(9)
			dw kw_printstrvar, str19
			dw kw_printint, var_r
			dw kw_printstrvar, str20
			dw kw_printint, arr_back
			dw kw_printstrvar, str21
			dw kw_printint, arr_back+18
			dw kw_printnl

			; main.bas 36: End If
if5_1:

			; main.bas 37: Else
			dw if3_e_go
if3_1:

			; main.bas 38: Print "No saving on this platform"
			dw kw_printstrvar, str22
			dw kw_printnl

			; main.bas 39: End If
if3_e:

			; main.bas 41: If FileSystem.Capability("SEQUENTIAL") Then
			dw fn_filesystem_capability, str6, var_filesystem_capability_capability
			dw kw_goto_ifzero_n, var_filesystem_capability_capability, if6_1

			; main.bas 42: h = FileSystem.Open("NOTES.TXT", FileSystem.ForWrite)
			dw fn_filesystem_open, str23, lit_2, var_h

			; main.bas 43: r = FileSystem.WriteLine(h, "Written by NTC BASIC")
			dw fn_filesystem_writeline, var_h, str24, var_r

			; main.bas 44: r = FileSystem.WriteLine(h, "Line two")
			dw fn_filesystem_writeline, var_h, str25, var_r

			; main.bas 45: r = FileSystem.Close(h)
			dw fn_filesystem_close, var_h, var_r

			; main.bas 46: Print "NOTES.TXT:"
			dw kw_printstrvar, str26
			dw kw_printnl

			; main.bas 47: h = FileSystem.Open("NOTES.TXT", FileSystem.ForRead)
			dw fn_filesystem_open, str23, lit_1, var_h

			; main.bas 48: Do While Not FileSystem.Eof(h)
do7_t:
			dw fn_filesystem_eof, var_h, var_filesystem_eof_eof
			dw kw_vtov, var_filesystem_eof_eof, tmp0
			dw kw_notv, tmp0, tmp0
			dw kw_goto_ifzero_n, tmp0, do7_e

			; main.bas 49: Print "> "; FileSystem.ReadLine(h)
			dw fn_filesystem_readline, var_h, var_filesystem_readline_readline
			dw kw_printstrvar, str27
			dw kw_printstrvar, var_filesystem_readline_readline
			dw kw_printnl

			; main.bas 50: Loop
			dw do7_t_go
do7_e:

			; main.bas 51: r = FileSystem.Close(h)
			dw fn_filesystem_close, var_h, var_r

			; main.bas 52: End If
if6_1:

			; main.bas 54: End
			dw kw_printnl0
			dw kw_printstrvar, str28
			dw kw_waitkey
			dw kw_stop

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

if3_e_go:			ld sp, if3_e
			jp ntc_xn
do7_t_go:			ld sp, do7_t
			jp ntc_xn

